// spec: specs/addbusiness-photos-step.md (2.1–2.2) · кейс: .qa/tests/addbusiness-photos-step/ADDBIZ-PHOTOS-05.md
// seed: tests/seed.user.spec.ts · ПРОД: черновик «QA-TEST …» удаляется в afterEach; запуск только с QA_REAL_WRITE=1.
// Генерация платная — POST …/Core/GenerateImage подменяется ответом { url: FAKE_AI_URL } (только Chromium:
// десктоп и Android/Pixel 7). Реальная генерация проверена вручную 01.11 (200, ~8 с).
import { test, expect, Page } from '@playwright/test';
import {
  FAKE_AI_URL, LOAD, REAL_WRITE, SKIP_REASON, Ctl, deleteDraft, goToPhotosStep, interceptDraft, styleCard,
} from './photos-step.helpers';

test.use({ storageState: '../auth/user.json', serviceWorkers: 'block' });
test.describe.configure({ mode: 'serial' });

async function generateAndToggle(page: Page, ctl: Ctl) {
  const card = styleCard(page, 'חזית ייצוגית');
  const aiImg = page.locator(`img[src="${FAKE_AI_URL}"]`);

  // «צור תמונה» → картинка в галерее («מה רצוי» #def18b; комментарий программиста; #366dae)
  await card.getByRole('button', { name: 'צור תמונה' }).click();
  await expect(page.getByText('תמונת ה-AI נוספה לגלריה.'), 'тост добавления').toBeVisible(LOAD);
  expect(ctl.generateCalls, 'один запрос GenerateImage').toHaveLength(1);
  await expect(page.getByText(/\(1\/10\)/), 'счётчик (1/10)').toBeVisible();
  await expect(page.getByText('נוצר באמצעות AI').first(), 'метка «נוצר באמצעות AI»').toBeVisible();
  await expect(aiImg.first(), 'сгенерированная картинка на странице').toBeVisible();
  const imgCountInGallery = await aiImg.count();
  await expect(card.getByRole('button', { name: 'הסר מהגלריה' })).toBeVisible();

  // «הסר מהגלריה» → (0/10), без сетевых запросов (комментарий программиста — «לחיצה נוספת מסירה אותה»)
  const writesBefore = ctl.writes.length;
  await card.getByRole('button', { name: 'הסר מהגלריה' }).click();
  await expect(page.getByText(/\(0\/10\)/), 'счётчик (0/10)').toBeVisible();
  await expect(card.getByRole('button', { name: 'הוסף לגלריה' })).toBeVisible();
  expect(ctl.writes.slice(writesBefore), 'удаление из галереи — без запросов').toEqual([]);

  // «הוסף לגלריה» → та же картинка, без новой генерации
  await card.getByRole('button', { name: 'הוסף לגלריה' }).click();
  await expect(page.getByText(/\(1\/10\)/), 'счётчик снова (1/10)').toBeVisible();
  await expect(card.getByRole('button', { name: 'הסר מהגלריה' })).toBeVisible();
  await expect(aiImg, 'та же картинка снова в галерее').toHaveCount(imgCountInGallery);
  await expect(page.getByText('נוצר באמצעות AI').first()).toBeVisible();
  expect(ctl.generateCalls, 'повторной генерации нет').toHaveLength(1);
  expect(ctl.writes.slice(writesBefore), 'возврат в галерею — без запросов').toEqual([]);
}

test.describe('Публикация бизнеса — «צור תמונה» и галерея', () => {
  let ctl: Ctl | null = null;

  test.beforeEach(() => test.skip(!REAL_WRITE, SKIP_REASON));
  test.afterEach(async ({ page }) => {
    if (ctl) await deleteDraft(page, ctl);
    ctl = null;
  });

  test('«צור תמונה» → в галерее с меткой AI; «הסר מהגלריה» / «הוסף לגלריה» без новой генерации #def18b @desktop @data', async ({ page }) => {
    ctl = await interceptDraft(page, 'def18b');
    await goToPhotosStep(page, ctl, 'בתי קפה ומסעדות');
    await generateAndToggle(page, ctl);
    expect(ctl.unexpected, 'кроме своего черновика на прод ничего не записано').toEqual([]);
  });

  test('Телефон: «צור תמונה» → галерея, удаление и возврат без новой генерации #def18b @android @data', async ({ page }) => {
    ctl = await interceptDraft(page, 'def18b');
    await goToPhotosStep(page, ctl, 'בתי קפה ומסעדות');
    await generateAndToggle(page, ctl);
    expect(ctl.unexpected, 'кроме своего черновика на прод ничего не записано').toEqual([]);
  });
});
